from pathlib import Path
header = '''#pragma once

#include <cstddef>
#include <cstdint>
#include <limits>

namespace growbox::app::output {

using OutputEndpointId = std::uint16_t;
using NormalizedOutputLevel = float;

inline constexpr OutputEndpointId kInvalidOutputEndpoint =
    std::numeric_limits<OutputEndpointId>::max();
inline constexpr std::size_t kOutputEndpointCapacity = 3U;

enum class BinaryOutputState : std::uint8_t { Off = 0U, On = 1U };

enum class OutputSource : std::uint8_t {
  None = 0U,
  Climate,
  Schedule,
  Manual,
  Safety,
  Lifecycle,
  Maintenance,
};

enum class SupervisorMode : std::uint8_t {
  BootLocked = 0U,
  Arming,
  Automatic,
  Recovering,
  Disabled,
  FaultLocked,
  MaintenanceLocked,
};

enum class TransportStatus : std::uint8_t { NotAttempted = 0U, Completed, Failed };

enum class TransportError : std::uint8_t {
  None = 0U,
  InvalidEndpoint,
  InvalidCommand,
  Unavailable,
  Busy,
  IoFailure,
};

constexpr bool isValidOutputEndpoint(OutputEndpointId endpoint) noexcept {
  return endpoint != kInvalidOutputEndpoint;
}

} // namespace growbox::app::output
'''
test = '''#include "climate/ClimateSemanticOutput.h"
#include "climate/output/OutputTypes.h"

#include <cassert>
#include <cstdint>
#include <type_traits>

using namespace growbox::app;

static_assert(std::is_same_v<output::OutputEndpointId, std::uint16_t>);
static_assert(std::is_same_v<climate_io::ClimateEndpointId, output::OutputEndpointId>);
static_assert(sizeof(output::OutputEndpointId) == 2U);
static_assert(sizeof(output::BinaryOutputState) == 1U);
static_assert(sizeof(output::OutputSource) == 1U);
static_assert(sizeof(output::SupervisorMode) == 1U);
static_assert(sizeof(output::TransportStatus) == 1U);
static_assert(sizeof(output::TransportError) == 1U);
static_assert(std::is_trivially_copyable_v<output::BinaryOutputState>);
static_assert(std::is_trivially_copyable_v<output::OutputSource>);
static_assert(std::is_trivially_copyable_v<output::SupervisorMode>);
static_assert(std::is_trivially_copyable_v<output::TransportStatus>);
static_assert(std::is_trivially_copyable_v<output::TransportError>);
static_assert(output::kOutputEndpointCapacity == 3U);

int main() {
  assert(!output::isValidOutputEndpoint(output::kInvalidOutputEndpoint));
  assert(output::isValidOutputEndpoint(0U));
  assert(climate_io::kUnmappedClimateEndpoint == output::kInvalidOutputEndpoint);
  return 0;
}
'''
Path('src/climate/output').mkdir(parents=True, exist_ok=True)
Path('test/test_output_types').mkdir(parents=True, exist_ok=True)
Path('src/climate/output/OutputTypes.h').write_text(header)
Path('test/test_output_types/test_main.cpp').write_text(test)
